-- ============================================================================
-- supabase/seed/places_seed.sql
-- OpenStreetMap Sensitive Places Seed (Schools, Hospitals, Bus Stops, Markets)
-- ============================================================================
-- Safe delete-then-insert: Deletes ONLY rows previously generated by this seed
-- (marked with source = 'osm_seed') so manually added places are never removed.
delete from public.places where source = 'osm_seed';

